/**
 * Compose
 * @description 将多个中间件函数组合成一个函数，按顺序执行
 * @param {Middleware[]} middlewares 中间件数组
 * @returns {(ctx: Context, next?: () => Promise<void> | void) => Promise<void>} 组合后的中间件函数
 */
function Compose(middlewares) {
    return function (ctx, next) {
        return new Promise(function (resolve) {
            var index = -1;
            // 中间件的返回值
            var middleWareQueueResults = Array.from({
                length: middlewares.length,
            }).fill(undefined);
            /**
             * loop
             * @description 迭代方法
             * @returns {unknown} 中间件执行结果
             */
            var loop = function () {
                // 迭代完成了
                if (index + 1 >= middlewares.length) {
                    Promise.all(middleWareQueueResults.filter(function (t) { return t instanceof Promise; })).then(function () {
                        // 真正的迭代完成
                        if (next) {
                            var p = next();
                            if (p && p.then) {
                                p.then(function () {
                                    resolve();
                                });
                                return;
                            }
                        }
                        resolve();
                    });
                    return;
                }
                index++;
                // 调用中间件方法
                // @ts-ignore - 中间件可能返回Promise或void
                middleWareQueueResults[index] = middlewares[index](ctx, function () { return loop(); });
                return middleWareQueueResults[index];
            };
            loop();
        });
    };
}
export default Compose;
